def verify_latest_response(latest_response):
    import re
    try:
        items = latest_response.get('items')
        if not items:
            return 0
        patterns = {
            'year': r'^\d{4}$',
            'month': r'^\d{4}-(0[1-9]|1[0-2])$',
            'day': r'^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$'
        }
        checked = False
        for item in items:
            rd = item.get('release_date')
            if rd is None:
                continue
            checked = True
            prec = item.get('release_date_precision')
            if prec in patterns:
                if not re.match(patterns[prec], str(rd)):
                    return -1
            else:
                if not any(re.match(p, str(rd)) for p in patterns.values()):
                    return -1
        return 1 if checked else 0
    except:
        return 0

